select
  tc.*,
  u.id createByUserId,
  u.name createByUserName
from t_customer tc
  left join t_user u on tc.create_by = u.id


    and tc.id in

      #{id}



    and tc.name like concat('%',#{search.name},'%')
    and tc.phone like concat('%',#{search.phone},'%')
    and tc.course_type like concat('%',#{search.courseType},'%')
    and tc.source like concat('%',#{search.source},'%')
    and tc.remark like concat('%',#{search.remark},'%')
    and tc.studying = #{search.studying}
    and tc.create_by = #{search.createBy}
    and tc.create_time >= #{search.createTimeStart}
    and tc.create_time <= #{search.createTimeEnd}
    and tc.create_time <= #{search.createTimePoint}
    and tc.create_time >= #{search.createTimePoint}
    and tc.course_expire_time >= #{search.courseExpireTimeStart}
    and tc.course_expire_time <= #{search.courseExpireTimeEnd}
    and tc.course_expire_time <= #{search.courseExpireTimePoint}
    and tc.course_expire_time >= #{search.courseExpireTimePoint}
    and tc.age = #{search.ageValue}
    and tc.age > #{search.ageValue}
    and tc.age < #{search.ageValue}
    and tc.age between #{search.ageMin} and #{search.ageMax}
    and tc.remaining_lessons = #{search.remainingLessonsValue}
    and tc.remaining_lessons > #{search.remainingLessonsValue}
    and tc.remaining_lessons < #{search.remainingLessonsValue}
    and tc.remaining_lessons between #{search.remainingLessonsMin} and #{search.remainingLessonsMax}


order by tc.studying desc,
         tc.remaining_lessons is null, tc.remaining_lessons asc,
         tc.course_expire_time is null, tc.course_expire_time asc,
         tc.id asc

