update t_customer
name = #{name}, phone = #{phone}, age = #{age}, course_type = #{courseType}, remaining_lessons = #{remainingLessons}, course_expire_time = #{courseExpireTime}, remark = #{remark}, source = #{source}, studying = #{studying}, clue_id = #{clueId},
where id = #{id}
